#!/usr/bin/env python3
# Generated by Phase: IMPLEMENT | Feature: #117
"""check-command-flags — every command flag the framework cites is declared by its command (#117). META-ONLY.

Scans the tracked text files under .claude/ and .context/templates/ (the two trees that reach a project:
framework core by factory-sync, templates by SETUP). A citation is `COMMAND --flag` (the command in capitals,
optionally `/`-prefixed) or `/command --flag` (lowercase needs the slash — `npm audit --omit` is not a
citation). Declared = the `--flag` token appears in .claude/commands/<command>.md. History is not rewritten:
the governance manifest and changelogs are not scanned.

Usage: check-command-flags.py [--root DIR]      exit 0 ok · 1 a ghost flag (file:line listed) · 2 infra
"""
from __future__ import annotations

import re
import subprocess
import sys
from pathlib import Path

ROOTS = (".claude/", ".context/templates/")
HISTORY = re.compile(r"(^|/)(governance_versions\.json|CHANGELOG[^/]*)$")
FLAG = re.compile(r"--[a-z][a-z0-9-]*")
ARG_VALUE = re.compile(r"--[a-z][a-z0-9-]*[ =]$")


def citations(commands: list[str]) -> re.Pattern:
    alt = "|".join(commands)
    return re.compile(rf"(?<![\w/.-])(?:/(?P<lower>{alt.lower()})|/?(?P<upper>{alt.upper()}))\b[ `]+(?P<flag>--[a-z][a-z0-9-]*)")


def scan(root: Path) -> list[str]:
    cmd_dir = root / ".claude/commands"
    declared = {f.stem.lower(): set(FLAG.findall(f.read_text(encoding="utf-8"))) for f in sorted(cmd_dir.glob("*.md"))}
    if not declared:
        raise RuntimeError(f"no command file under {cmd_dir} — nothing declares a flag")
    files = subprocess.run(["git", "-C", str(root), "ls-files", "--", *ROOTS], capture_output=True, text=True, check=True).stdout.split()
    pat, ghosts = citations(sorted(declared)), []
    for rel in files:
        if HISTORY.search(rel):
            continue
        try:
            text = (root / rel).read_text(encoding="utf-8")
        except (UnicodeDecodeError, FileNotFoundError):
            continue
        for n, line in enumerate(text.splitlines(), 1):
            for m in pat.finditer(line):
                if ARG_VALUE.search(line[:m.start()]):
                    continue   # `--phase SETUP --format`: the command name is another flag's value, not a citation
                cmd = (m.group("lower") or m.group("upper")).lower()
                if m.group("flag") not in declared[cmd]:
                    ghosts.append(f"{rel}:{n}: {cmd.upper()} {m.group('flag')} — .claude/commands/{cmd}.md declares no such flag")
    return ghosts


def main(argv: list[str]) -> int:
    root = Path(argv[argv.index("--root") + 1]).resolve() if "--root" in argv else Path(__file__).resolve().parent.parent
    try:
        ghosts = scan(root)
    except (RuntimeError, subprocess.CalledProcessError, OSError) as e:
        print(f"check-command-flags: could not scan ({e})", file=sys.stderr)
        return 2
    for g in ghosts:
        print(f"  ✗ {g}")
    if ghosts:
        print(f"[FAIL] check-command-flags: {len(ghosts)} citation(s) of a flag no command declares — say what the operator does today instead, or declare the flag in its command")
        return 1
    print("[OK] check-command-flags: every cited command flag is declared by its command")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
